function(container, apiUrl, tables) {
  const reportTbody = container.querySelector('#report-tbody');
  const detailPanel = container.querySelector('#detail-panel');
  const detailHeader = container.querySelector('#detail-header');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');
  const templateFilter = container.querySelector('[data-testid="template-filter"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-btn"]');
  const resendBtn = container.querySelector('[data-testid="resend-btn"]');
  const previewBtn = container.querySelector('[data-testid="preview-btn"]');
  const previewModal = container.querySelector('#preview-modal');
  const closePreviewBtn = container.querySelector('#close-preview');

  let allReports = [];
  let selectedReport = null;

  // テーブルインデックス（生成済みレポート = 0）
  const REPORT_TABLE_IDX = 0;
  const USER_TABLE_IDX = 0;
  const DELIVERY_HISTORY_IDX = 1;

  // レポート一覧を取得・表示
  async function loadReports() {
    const reports = await window.aivicApi.list(REPORT_TABLE_IDX);
    if (!reports) return;

    allReports = reports;
    renderReportList(allReports);
  }

  // レポート一覧をレンダリング
  function renderReportList(reports) {
    reportTbody.innerHTML = '';
    reports.forEach(report => {
      const row = document.createElement('tr');
      row.style.cssText = 'background: rgba(255,255,255,0.02); cursor: pointer; transition: background 0.2s;';
      row.dataset.id = report.id;

      const statusColor = {
        '配信済み': '#22c55e',
        '未配信': '#f59e0b',
        '配信失敗': '#ef4444'
      }[report.配信ステータス] || '#9ca3af';

      row.innerHTML = `
        <td style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.08); color: var(--text);">
          <div style="font-weight: 500;">${report.レポートタイトル || '無題'}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${new Date(report.生成日時).toLocaleDateString('ja-JP')}</div>
        </td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.08);">
          <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 10px; font-weight: 600;">${report.配信ステータス || '未配信'}</span>
        </td>
      `;

      row.addEventListener('click', () => selectReport(report));
      row.addEventListener('mouseenter', () => row.style.background = 'rgba(255,255,255,0.08)');
      row.addEventListener('mouseleave', () => row.style.background = 'rgba(255,255,255,0.02)');

      reportTbody.appendChild(row);
    });
  }

  // レポート選択時の詳細表示
  async function selectReport(report) {
    selectedReport = report;

    // ヘッダー更新
    container.querySelector('#detail-title').textContent = report.レポートタイトル || '無題';
    const startDate = new Date(report.レポート期間開始日).toLocaleDateString('ja-JP');
    const endDate = new Date(report.レポート期間終了日).toLocaleDateString('ja-JP');
    container.querySelector('#detail-period').textContent = `${startDate} ～ ${endDate}`;
    container.querySelector('#detail-template').textContent = report.テンプレート名 || '—';
    container.querySelector('#detail-generated').textContent = new Date(report.生成日時).toLocaleString('ja-JP');

    // KPI表示
    container.querySelector('#kpi-contracts').textContent = report.成約件数 || 0;
    container.querySelector('#kpi-revenue').textContent = `¥${(report.売上金額 || 0).toLocaleString()}`;
    container.querySelector('#kpi-achievement').textContent = report.達成率 ? `${report.達成率}%` : '—';

    // コンテンツプレビュー
    container.querySelector('#content-preview').textContent = report.レポート内容 || '内容なし';

    // ユーザー情報取得
    const users = await window.aivicApi.list(USER_TABLE_IDX);
    const user = users?.find(u => u.id === report.ユーザーID);
    container.querySelector('#user-name').textContent = user?.氏名 || '—';
    container.querySelector('#user-email').textContent = user?.メールアドレス || '—';

    // 配信履歴取得
    const deliveryHistory = await window.aivicApi.list(DELIVERY_HISTORY_IDX);
    const history = deliveryHistory?.filter(h => h.生成済みレポートID === report.id) || [];
    renderDeliveryTimeline(history);

    // ボタン有効化
    resendBtn.disabled = false;
    previewBtn.disabled = false;

    // 行のハイライト
    container.querySelectorAll('#report-tbody tr').forEach(tr => {
      tr.style.background = tr.dataset.id === report.id ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.02)';
    });
  }

  // 配信履歴タイムラインをレンダリング
  function renderDeliveryTimeline(history) {
    const timeline = container.querySelector('#delivery-timeline');
    if (!history || history.length === 0) {
      timeline.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 16px 0;">配信履歴なし</div>';
      return;
    }

    timeline.innerHTML = history.map(h => {
      const statusColor = {
        '成功': '#22c55e',
        '失敗': '#ef4444',
        '保留中': '#f59e0b'
      }[h.配信ステータス] || '#9ca3af';

      return `
        <div style="padding: 8px; border-left: 2px solid ${statusColor}; margin-bottom: 8px; background: rgba(0,0,0,0.2); border-radius: 4px;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
            <span style="font-weight: 500; color: var(--text);">${h.配信先メールアドレス}</span>
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 2px; font-size: 9px; font-weight: 600;">${h.配信ステータス}</span>
          </div>
          <div style="font-size: 10px; color: var(--text-muted);">${new Date(h.配信日時).toLocaleString('ja-JP')}</div>
          ${h.開封フラグ ? `<div style="font-size: 10px; color: #22c55e; margin-top: 2px;">✓ 開封済み (${new Date(h.開封日時).toLocaleString('ja-JP')})</div>` : ''}
          ${h.エラーメッセージ ? `<div style="font-size: 10px; color: #ef4444; margin-top: 2px;">エラー: ${h.エラーメッセージ}</div>` : ''}
        </div>
      `;
    }).join('');
  }

  // フィルタ適用
  function applyFilters() {
    const status = statusFilter.value;
    const template = templateFilter.value;

    const filtered = allReports.filter(r => {
      const matchStatus = !status || r.配信ステータス === status;
      const matchTemplate = !template || r.テンプレート名 === template;
      return matchStatus && matchTemplate;
    });

    renderReportList(filtered);
  }

  // CSVエクスポート
  exportBtn.addEventListener('click', async () => {
    const reports = await window.aivicApi.list(REPORT_TABLE_IDX);
    if (!reports || reports.length === 0) return;

    const headers = ['レポートID', 'レポートタイトル', '生成日時', 'テンプレート名', '配信ステータス', '成約件数', '売上金額', '達成率'];
    const rows = reports.map(r => [
      r.id,
      r.レポートタイトル || '',
      new Date(r.生成日時).toLocaleString('ja-JP'),
      r.テンプレート名 || '',
      r.配信ステータス || '',
      r.成約件数 || 0,
      r.売上金額 || 0,
      r.達成率 || ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `reports_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  });

  // 再配信
  resendBtn.addEventListener('click', async () => {
    if (!selectedReport) return;

    const updated = await window.aivicApi.update(REPORT_TABLE_IDX, selectedReport.id, {
      配信ステータス: '未配信',
      更新日時: new Date().toISOString()
    });

    if (updated) {
      selectedReport = updated;
      loadReports();
      alert('再配信キューに追加されました');
    }
  });

  // プレビュー
  previewBtn.addEventListener('click', () => {
    if (!selectedReport) return;
    container.querySelector('#modal-content').textContent = selectedReport.レポート内容 || '内容なし';
    previewModal.style.display = 'flex';
  });

  closePreviewBtn.addEventListener('click', () => {
    previewModal.style.display = 'none';
  });

  previewModal.addEventListener('click', (e) => {
    if (e.target === previewModal) previewModal.style.display = 'none';
  });

  // フィルタイベント
  statusFilter.addEventListener('change', applyFilters);
  templateFilter.addEventListener('change', applyFilters);

  // 初期ロード
  loadReports();
}

function(container, apiUrl, tables) {
  const userTable = tables[0];
  const salesActivityTable = tables[1];
  const customerTable = tables[2];
  const contractTable = tables[3];
  const templateTable = tables[4];
  const indicatorTable = tables[5];

  let selectedUsers = new Set();
  let selectedIndicators = new Set();
  let previewData = { revenue: 0, contracts: 0, activities: 0, companies: [], users: [] };

  // ===== 初期化: ユーザー一覧を読み込み =====
  async function initUsers() {
    const users = await window.aivicApi.list(0);
    if (!users) return;

    const userList = container.querySelector('#user-list');
    userList.innerHTML = '';

    users.forEach(user => {
      if (user.ステータス !== '有効') return;
      const label = document.createElement('label');
      label.style.cssText = 'display: flex; align-items: center; gap: 6px; padding: 4px; cursor: pointer; font-size: 12px; color: var(--text);';

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = user.ユーザーID;
      checkbox.style.accentColor = 'var(--primary)';
      checkbox.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedUsers.add(user.ユーザーID);
        } else {
          selectedUsers.delete(user.ユーザーID);
        }
        updatePreview();
      });

      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(`${user.氏名} (${user.部門})`));
      userList.appendChild(label);
    });
  }

  // ===== 初期化: 成果指標一覧を読み込み =====
  async function initIndicators() {
    const indicators = await window.aivicApi.list(5);
    if (!indicators) return;

    const indicatorList = container.querySelector('#indicator-list');
    indicatorList.innerHTML = '';

    indicators.forEach(indicator => {
      if (!indicator.有効フラグ) return;
      const label = document.createElement('label');
      label.style.cssText = 'display: flex; align-items: center; gap: 6px; padding: 4px; cursor: pointer; font-size: 11px; color: var(--text);';

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = indicator.成果指標ID;
      checkbox.checked = true;
      checkbox.style.accentColor = 'var(--primary)';
      checkbox.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedIndicators.add(indicator.成果指標ID);
        } else {
          selectedIndicators.delete(indicator.成果指標ID);
        }
      });

      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(indicator.指標名));
      indicatorList.appendChild(label);
      selectedIndicators.add(indicator.成果指標ID);
    });
  }

  // ===== 全選択 / 全解除 =====
  container.querySelector('#select-all-btn').addEventListener('click', () => {
    container.querySelectorAll('#user-list input[type="checkbox"]').forEach(cb => {
      cb.checked = true;
      selectedUsers.add(cb.value);
    });
    updatePreview();
  });

  container.querySelector('#deselect-all-btn').addEventListener('click', () => {
    container.querySelectorAll('#user-list input[type="checkbox"]').forEach(cb => {
      cb.checked = false;
      selectedUsers.delete(cb.value);
    });
    updatePreview();
  });

  // ===== プレビュー更新 =====
  async function updatePreview() {
    const monthInput = container.querySelector('#target-month').value;
    if (!monthInput || selectedUsers.size === 0) {
      container.querySelector('#preview-summary').innerHTML = '<div style="grid-column: 1/-1; text-align: center; color: var(--text-muted); font-size: 12px; padding: 12px;">対象年月とユーザーを選択してください</div>';
      return;
    }

    const [year, month] = monthInput.split('-');
    const startDate = new Date(year, parseInt(month) - 1, 1);
    const endDate = new Date(year, parseInt(month), 0);

    // 営業活動と成約データを集計
    const activities = await window.aivicApi.list(1);
    const contracts = await window.aivicApi.list(3);
    const customers = await window.aivicApi.list(2);

    if (!activities || !contracts) return;

    let totalRevenue = 0;
    let totalContracts = 0;
    let totalActivities = 0;
    const companyMap = {};
    const userMap = {};

    // 営業活動集計
    activities.forEach(act => {
      if (!selectedUsers.has(act.ユーザーID)) return;
      const actDate = new Date(act.活動日);
      if (actDate >= startDate && actDate <= endDate) {
        totalActivities++;
        if (!userMap[act.ユーザーID]) {
          userMap[act.ユーザーID] = { revenue: 0, contracts: 0, name: '' };
        }
      }
    });

    // 成約集計
    contracts.forEach(con => {
      if (!selectedUsers.has(con.ユーザーID)) return;
      const conDate = new Date(con.成約日);
      if (conDate >= startDate && conDate <= endDate) {
        totalRevenue += con.成約金額 || 0;
        totalContracts++;

        if (!userMap[con.ユーザーID]) {
          userMap[con.ユーザーID] = { revenue: 0, contracts: 0, name: '' };
        }
        userMap[con.ユーザーID].revenue += con.成約金額 || 0;
        userMap[con.ユーザーID].contracts++;

        // 企業別集計
        const customer = customers?.find(c => c.顧客企業ID === con.顧客企業ID);
        if (customer) {
          if (!companyMap[customer.企業名]) {
            companyMap[customer.企業名] = { revenue: 0, contracts: 0 };
          }
          companyMap[customer.企業名].revenue += con.成約金額 || 0;
          companyMap[customer.企業名].contracts++;
        }
      }
    });

    // ユーザー名を取得
    const users = await window.aivicApi.list(0);
    users?.forEach(u => {
      if (userMap[u.ユーザーID]) {
        userMap[u.ユーザーID].name = u.氏名;
      }
    });

    previewData = {
      revenue: totalRevenue,
      contracts: totalContracts,
      activities: totalActivities,
      companies: Object.entries(companyMap)
        .map(([name, data]) => ({ name, ...data }))
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 5),
      users: Object.entries(userMap)
        .map(([id, data]) => ({ id, ...data }))
        .sort((a, b) => b.revenue - a.revenue)
    };

    // UI更新
    container.querySelector('#preview-revenue').textContent = `¥${totalRevenue.toLocaleString()}`;
    container.querySelector('#preview-contracts').textContent = `${totalContracts}件`;
    container.querySelector('#preview-activities').textContent = `${totalActivities}件`;
    container.querySelector('#preview-user-count').textContent = `${selectedUsers.size}名`;

    // 企業別テーブル
    const companyTbody = container.querySelector('#preview-company-tbody');
    if (previewData.companies.length > 0) {
      companyTbody.innerHTML = previewData.companies.map(c => `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
          <td style="padding: 4px; color: var(--text);">${c.name}</td>
          <td style="text-align: right; padding: 4px; color: #ffd700;">¥${c.revenue.toLocaleString()}</td>
          <td style="text-align: right; padding: 4px; color: var(--text);">${c.contracts}件</td>
        </tr>
      `).join('');
    } else {
      companyTbody.innerHTML = '<tr><td colspan="3" style="text-align: center; padding: 8px; color: var(--text-muted);">データなし</td></tr>';
    }

    // ユーザー別テーブル
    const userTbody = container.querySelector('#preview-user-tbody');
    if (previewData.users.length > 0) {
      userTbody.innerHTML = previewData.users.map(u => `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
          <td style="padding: 4px; color: var(--text);">${u.name}</td>
          <td style="text-align: right; padding: 4px; color: #ffd700;">¥${u.revenue.toLocaleString()}</td>
          <td style="text-align: right; padding: 4px; color: #dc143c;">${u.contracts}件</td>
        </tr>
      `).join('');
    } else {
      userTbody.innerHTML = '<tr><td colspan="3" style="text-align: center; padding: 8px; color: var(--text-muted);">データなし</td></tr>';
    }
  }

  // ===== プレビューボタン =====
  container.querySelector('#preview-btn').addEventListener('click', updatePreview);

  // ===== 生成実行 =====
  container.querySelector('#generate-btn').addEventListener('click', async () => {
    const monthInput = container.querySelector('#target-month').value;
    const templateId = container.querySelector('#template-select').value;

    if (!monthInput || selectedUsers.size === 0 || !templateId) {
      alert('対象年月、ユーザー、テンプレートを選択してください');
      return;
    }

    const progressOverlay = container.querySelector('#progress-overlay');
    progressOverlay.style.display = 'flex';

    try {
      const [year, month] = monthInput.split('-');
      const startDate = new Date(year, parseInt(month) - 1, 1);
      const endDate = new Date(year, parseInt(month), 0);

      let progress = 0;
      const updateProgress = (p) => {
        progress = p;
        container.querySelector('#progress-bar').style.width = `${p}%`;
        container.querySelector('#progress-text').textContent = `${p}%`;
      };

      // ユーザーごとにレポート生成
      const userArray = Array.from(selectedUsers);
      for (let i = 0; i < userArray.length; i++) {
        const userId = userArray[i];
        updateProgress(Math.round((i / userArray.length) * 100));

        const reportData = {
          テンプレートID: templateId,
          ユーザーID: userId,
          レポート期間開始日: startDate.toISOString(),
          レポート期間終了日: endDate.toISOString(),
          生成日時: new Date().toISOString(),
          レポートタイトル: `${year}年${month}月 営業成果レポート`,
          レポート内容: JSON.stringify(previewData),
          配信ステータス: '未配信',
          成約件数: previewData.contracts,
          営業活動件数: previewData.activities,
          作成者ID: userId
        };

        await window.aivicApi.save(4, reportData);
      }

      updateProgress(100);
      setTimeout(() => {
        progressOverlay.style.display = 'none';
        alert(`${userArray.length}件のレポートを生成しました`);
        window.showScreen('scr-1782111929733');
      }, 500);
    } catch (err) {
      progressOverlay.style.display = 'none';
      alert('レポート生成に失敗しました: ' + err.message);
    }
  });

  // ===== 戻るボタン =====
  container.querySelector('#back-button').addEventListener('click', () => {
    window.showScreen('scr-1782111949772');
  });

  // ===== 初期化実行 =====
  initUsers();
  initIndicators();

  // 対象年月変更時にプレビュー更新
  container.querySelector('#target-month').addEventListener('change', updatePreview);
  container.querySelector('#template-select').addEventListener('change', updatePreview);
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const TABLE_USERS = 0;
  const TABLE_GENERATED_REPORTS = 1;
  const TABLE_DELIVERY_HISTORY = 2;

  // DOM要素の取得
  const reportSelect = container.querySelector('#report-select');
  const reportDetail = container.querySelector('#report-detail');
  const reportTitle = container.querySelector('#report-title');
  const reportPeriod = container.querySelector('#report-period');
  const reportContracts = container.querySelector('#report-contracts');
  const reportActivities = container.querySelector('#report-activities');
  const userList = container.querySelector('#user-list');
  const selectedCount = container.querySelector('#selected-count');
  const deliveryMethod = container.querySelectorAll('input[name="delivery-method"]');
  const scheduleType = container.querySelectorAll('input[name="schedule-type"]');
  const scheduledDatetime = container.querySelector('#scheduled-datetime');
  const deliveryDatetime = container.querySelector('#delivery-datetime');
  const deliveryMessage = container.querySelector('#delivery-message');
  const previewUsers = container.querySelector('#preview-users');
  const previewMessage = container.querySelector('#preview-message');
  const executeBtn = container.querySelector('#execute-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const historyLink = container.querySelector('#history-link');
  const statusDisplay = container.querySelector('#status-display');
  const statusText = container.querySelector('#status-text');

  let selectedReport = null;
  let selectedUsers = [];

  // 初期化: レポート一覧を取得して select に反映
  async function initReports() {
    const reports = await window.aivicApi.list(TABLE_GENERATED_REPORTS);
    if (!reports) return;

    // 既存の option を保持しつつ、データベースから取得したレポートを追加
    reports.forEach(report => {
      const option = document.createElement('option');
      option.value = report.id;
      option.textContent = report.レポートタイトル || `レポート ${report.id}`;
      reportSelect.appendChild(option);
    });
  }

  // レポート選択時の処理
  reportSelect.addEventListener('change', async (e) => {
    const reportId = e.target.value;
    if (!reportId) {
      reportDetail.style.display = 'none';
      selectedReport = null;
      return;
    }

