  const kpiActivities = container.querySelector('[data-testid="kpi-activities"]');
  const kpiUnitPrice = container.querySelector('[data-testid="kpi-unit-price"]');
  const kpiConversion = container.querySelector('[data-testid="kpi-conversion"]');

