  const metricCheckboxes = {
    revenue: container.querySelector('[data-testid="metric-revenue"]'),
    contracts: container.querySelector('[data-testid="metric-contracts"]'),
    activities: container.querySelector('[data-testid="metric-activities"]'),
    unitPrice: container.querySelector('[data-testid="metric-unit-price"]'),
    conversion: container.querySelector('[data-testid="metric-conversion"]')
  };

  // 集計結果データ
  let aggregatedData = {
    totalRevenue: 0,
    totalContracts: 0,
    totalActivities: 0,
    uniqueCustomers: 0,
    conversionRate: 0,
    byUser: []
  };

  // 初期化: 日付デフォルト値（当月）
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  periodStartInput.valueAsDate = firstDay;
  periodEndInput.valueAsDate = today;

  // ユーザーフィルタ初期化
  async function initUserFilter() {
    try {
      const users = await window.aivicApi.list(TABLE_USERS);
      if (users && users.length > 0) {
        users.forEach(user => {
          const option = document.createElement('option');
          option.value = user.id || user.ユーザーID;
          option.textContent = user.氏名 || user.ユーザー名 || 'Unknown';
          userFilterSelect.appendChild(option);
        });
      }
    } catch (e) {
      console.error('Failed to load users:', e);
    }
  }

  // 顧客フィルタ初期化
  async function initCustomerFilter() {
    try {
      const customers = await window.aivicApi.list(TABLE_CUSTOMERS);
      if (customers && customers.length > 0) {
        customers.forEach(customer => {
          const option = document.createElement('option');
          option.value = customer.id || customer.顧客企業ID;
          option.textContent = customer.企業名 || 'Unknown';
          customerFilterSelect.appendChild(option);
        });
      }
    } catch (e) {
      console.error('Failed to load customers:', e);
    }
  }

  // 営業活動データ読み込み
  loadActivityBtn.addEventListener('click', async () => {
    try {
      loadingState.style.display = 'block';
      const activities = await window.aivicApi.list(TABLE_ACTIVITIES);
      if (activities) {
        console.log('Loaded activities:', activities.length);
      }
      loadingState.style.display = 'none';
    } catch (e) {
      console.error('Failed to load activities:', e);
      loadingState.style.display = 'none';
    }
  });

  // 成約データ読み込み
  loadContractBtn.addEventListener('click', async () => {
    try {
      loadingState.style.display = 'block';
      const contracts = await window.aivicApi.list(TABLE_CONTRACTS);
      if (contracts) {
        console.log('Loaded contracts:', contracts.length);
      }
      loadingState.style.display = 'none';
    } catch (e) {
      console.error('Failed to load contracts:', e);
      loadingState.style.display = 'none';
    }
  });

  // 集計処理
  aggregateBtn.addEventListener('click', async () => {
    try {
      loadingState.style.display = 'block';

      const periodStart = periodStartInput.valueAsDate;
      const periodEnd = periodEndInput.valueAsDate;
      const userId = userFilterSelect.value;
      const customerId = customerFilterSelect.value;

      // データ取得
      const activities = await window.aivicApi.list(TABLE_ACTIVITIES) || [];
      const contracts = await window.aivicApi.list(TABLE_CONTRACTS) || [];

      // フィルタリング
      let filteredActivities = activities;
      let filteredContracts = contracts;

      if (periodStart && periodEnd) {
        const start = new Date(periodStart);
        const end = new Date(periodEnd);
        end.setHours(23, 59, 59, 999);

        filteredActivities = activities.filter(a => {
          const actDate = new Date(a.活動日 || a.activityDate);
          return actDate >= start && actDate <= end;
        });

        filteredContracts = contracts.filter(c => {
          const conDate = new Date(c.成約日 || c.contractDate);
          return conDate >= start && conDate <= end;
        });
      }

      if (userId && userId !== 'all') {
        filteredActivities = filteredActivities.filter(a => a.ユーザーID === userId || a.userId === userId);
        filteredContracts = filteredContracts.filter(c => c.ユーザーID === userId || c.userId === userId);
      }

      if (customerId && customerId !== 'all') {
        filteredActivities = filteredActivities.filter(a => a.顧客名 === customerId);
        filteredContracts = filteredContracts.filter(c => c.顧客企業ID === customerId);
      }

      // 集計計算
      const totalRevenue = filteredContracts.reduce((sum, c) => sum + (c.成約金額 || c.contractAmount || 0), 0);
      const totalContracts = filteredContracts.length;
      const totalActivities = filteredActivities.length;
      const uniqueCustomers = new Set(filteredContracts.map(c => c.顧客企業ID || c.customerId)).size;
      const conversionRate = totalActivities > 0 ? Math.round((totalContracts / totalActivities) * 100) : 0;
      const unitPrice = uniqueCustomers > 0 ? Math.round(totalRevenue / uniqueCustomers) : 0;

      aggregatedData = {
        totalRevenue,
        totalContracts,
        totalActivities,
        uniqueCustomers,
        conversionRate,
        unitPrice,
        byUser: groupByUser(filteredActivities, filteredContracts)
      };

      // KPI 更新
      if (metricCheckboxes.revenue.checked) {
        kpiRevenue.textContent = `¥${totalRevenue.toLocaleString()}`;
      }
      if (metricCheckboxes.contracts.checked) {
        kpiContracts.textContent = `${totalContracts}件`;
      }
      if (metricCheckboxes.activities.checked) {
        kpiActivities.textContent = `${totalActivities}件`;
      }
      if (metricCheckboxes.unitPrice.checked) {
        kpiUnitPrice.textContent = `¥${unitPrice.toLocaleString()}`;
      }
      if (metricCheckboxes.conversion.checked) {
        kpiConversion.textContent = `${conversionRate}%`;
      }

      // プレビューテーブル更新
      updatePreviewTable(aggregatedData.byUser);

      loadingState.style.display = 'none';
    } catch (e) {
      console.error('Aggregation error:', e);
      loadingState.style.display = 'none';
    }
  });

  // ユーザー別グループ化
  function groupByUser(activities, contracts) {
    const userMap = {};

    activities.forEach(a => {
      const uid = a.ユーザーID || a.userId;
      if (!userMap[uid]) {
        userMap[uid] = {
          userId: uid,
          userName: a.ユーザー名 || 'Unknown',
          revenue: 0,
          contracts: 0,
          activities: 0
        };
      }
      userMap[uid].activities += 1;
    });

    contracts.forEach(c => {
      const uid = c.ユーザーID || c.userId;
      if (!userMap[uid]) {
        userMap[uid] = {
          userId: uid,
          userName: c.ユーザー名 || 'Unknown',
          revenue: 0,
          contracts: 0,
          activities: 0
        };
      }
      userMap[uid].revenue += c.成約金額 || c.contractAmount || 0;
      userMap[uid].contracts += 1;
    });

    return Object.values(userMap);
  }

  // プレビューテーブル更新
  function updatePreviewTable(byUser) {
    previewTbody.innerHTML = '';
    if (byUser.length === 0) {
      previewTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="5" style="padding: 12px 8px; text-align: center; color: var(--text-muted); font-size: 11px;">該当データなし</td></tr>';
      return;
    }

    byUser.forEach((row, idx) => {
      const convRate = row.activities > 0 ? Math.round((row.contracts / row.activities) * 100) : 0;
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid rgba(255,255,255,0.05)';
      if (idx % 2 === 0) tr.style.background = 'rgba(0,0,0,0.1)';

      tr.innerHTML = `
        <td style="padding: 6px 8px; color: var(--text);">${row.userName}</td>
        <td style="padding: 6px 8px; text-align: right; color: #d4af37; font-weight: 600;">¥${row.revenue.toLocaleString()}</td>
        <td style="padding: 6px 8px; text-align: center; color: #e74c3c; font-weight: 600;">${row.contracts}</td>
        <td style="padding: 6px 8px; text-align: center; color: #3498db;">${row.activities}</td>
        <td style="padding: 6px 8px; text-align: right; color: #f39c12; font-weight: 600;">${convRate}%</td>
      `;
      previewTbody.appendChild(tr);
    });
  }

  // CSV 出力
  exportCsvBtn.addEventListener('click', () => {
    if (aggregatedData.byUser.length === 0) {
      alert('出力するデータがありません。先に集計を実行してください。');
      return;
    }

    const headers = ['営業担当者', '売上高', '成約件数', '活動件数', '成約率'];
    const rows = aggregatedData.byUser.map(row => {
      const convRate = row.activities > 0 ? Math.round((row.contracts / row.activities) * 100) : 0;
      return [
        row.userName,
        row.revenue,
        row.contracts,
        row.activities,
        convRate + '%'
      ];
    });

    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(v => `"${v}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `成果指標集計_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // レポート生成へ
  generateReportBtn.addEventListener('click', () => {
    if (aggregatedData.totalActivities === 0) {
      alert('集計データがありません。先に集計を実行してください。');
      return;
    }
    // レポート自動生成・配信画面へ遷移
    window.showScreen('scr-1782111910177');
  });

  // 初期化実行
  initUserFilter();
  initCustomerFilter();
}

