        item.innerHTML = `
          <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 4px;">
            <div style="font-weight: 600; color: var(--text);">${report.レポートタイトル || 'レポート'}</div>
            <span style="background: ${report.配信ステータス === '配信済み' ? 'rgba(34,139,34,0.3)' : 'rgba(220,20,60,0.3)'}; color: ${report.配信ステータス === '配信済み' ? '#90ee90' : '#ff6b6b'}; padding: 2px 6px; border-radius: 3px; font-size: 10px;">${report.配信ステータス || '未配信'}</span>
          </div>
          <div style="color: var(--text-muted); margin-bottom: 4px;">期間: ${report.レポート期間開始日} ～ ${report.レポート期間終了日}</div>
          <div style="color: var(--text-muted);">生成: ${report.生成日時 || '—'}</div>
        `;
        reportHistoryList.appendChild(item);
      });
    } catch (err) {
      console.error('Report history load error:', err);
    }
  }

  // 生成済みレポート一覧パネルの表示/非表示
  const showHistoryBtn = document.createElement('button');
  showHistoryBtn.textContent = '📋 生成済みレポート';
  showHistoryBtn.style.cssText = 'position: fixed; bottom: 16px; right: 16px; padding: 8px 12px; background: var(--primary); color: #fff; border: none; border-radius: 4px; font-size: 12px; font-weight: 600; cursor: pointer; z-index: 99;';
  showHistoryBtn.addEventListener('click', () => {
    reportHistoryPanel.style.display = reportHistoryPanel.style.display === 'flex' ? 'none' : 'flex';
    loadReportHistory();
  });
  container.appendChild(showHistoryBtn);

  closeHistoryBtn.addEventListener('click', () => {
    reportHistoryPanel.style.display = 'none';
  });

  // フォーム変更時にプレビュー更新
  [periodStartInput, periodEndInput, userSelect, customerSelect].forEach(el => {
    el.addEventListener('change', () => {
      initializeData();
    });
  });

  // 初期化
  initializeData();
}
